-- Arbeitsrecht Berufsbildung > Pflichten von Arbeitgebern > Einhaltung von Arbeitsschutzvorschriften (ArbSchG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb die Arbeitsschutzvorschriften für einen Fachinformatiker einhalten?', 2, '[{"text": "Ja", "correct": true, "because": "Das ArbSchG verpflichtet den Arbeitgeber dazu"}, {"text": "Nein", "correct": false, "because": "Arbeitsschutz ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb einen Fachinformatiker ohne ergonomischen Arbeitsplatz beschäftigen?', 2, '[{"text": "Nein", "correct": true, "because": "ArbSchG fordert ergonomische Arbeitsbedingungen"}, {"text": "Ja", "correct": false, "because": "Ergonomie ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb einen Fachinformatiker über Arbeitsschutz unterweisen?', 2, '[{"text": "Ja", "correct": true, "because": "ArbSchG § 12 verlangt Unterweisung"}, {"text": "Nein", "correct": false, "because": "Unterweisung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Betrieb einen Fachinformatiker ohne Pausen arbeiten lassen?', 2, '[{"text": "Nein", "correct": true, "because": "ArbSchG § 3 schreibt Pausen vor"}, {"text": "Ja", "correct": false, "because": "Pausen sind gesetzlich geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb Gefährdungsbeurteilungen für einen Fachinformatiker durchführen?', 2, '[{"text": "Ja", "correct": true, "because": "ArbSchG § 5 fordert Gefährdungsbeurteilungen"}, {"text": "Nein", "correct": false, "because": "Pflicht für alle Arbeitsplätze"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz verpflichtet einen Betrieb, Arbeitsschutzvorschriften für einen Fachinformatiker einzuhalten?', 2, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "Regelt den Arbeitsschutz"}, {"text": "Berufsbildungsgesetz (BBiG)", "correct": false, "because": "Regelt die Ausbildung"}, {"text": "Kündigungsschutzgesetz (KSchG)", "correct": false, "because": "Regelt Kündigungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb tun, um den Arbeitsschutz eines Fachinformatikers zu gewährleisten?', 3, '[{"text": "Gefährdungen beurteilen und Maßnahmen umsetzen", "correct": true, "because": "ArbSchG § 5 verlangt dies"}, {"text": "Nur Arbeitsmittel bereitstellen", "correct": false, "because": "Zu unvollständig"}, {"text": "Den Auszubildenden allein verantwortlich machen", "correct": false, "because": "Betrieb ist verpflichtet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme gehört zur Einhaltung des Arbeitsschutzes für einen Fachinformatiker?', 3, '[{"text": "Ergonomische Gestaltung des Arbeitsplatzes", "correct": true, "because": "ArbSchG § 3 fordert dies"}, {"text": "Nur lange Arbeitszeiten anordnen", "correct": false, "because": "Widerspricht Pausenregelung"}, {"text": "Keine Unterweisung bieten", "correct": false, "because": "Unterweisung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, Arbeitsschutzvorschriften für einen Fachinformatiker sicherzustellen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "ArbSchG legt dies fest"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat keine direkte Pflicht"}, {"text": "Der Auszubildende selbst", "correct": false, "because": "Betrieb trägt Verantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb Arbeitsschutzvorschriften für einen Fachinformatiker nicht einhält?', 3, '[{"text": "Behörden können Maßnahmen anordnen", "correct": true, "because": "ArbSchG Verstöße werden sanktioniert"}, {"text": "Der Auszubildende übernimmt die Verantwortung", "correct": false, "because": "Nicht seine Pflicht"}, {"text": "Keine Konsequenzen", "correct": false, "because": "Verstoß hat Folgen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen muss ein Betrieb zur Einhaltung des Arbeitsschutzes für einen Fachinformatiker ergreifen?', 4, '[{"text": "Gefährdungsbeurteilung durchführen", "correct": true, "because": "ArbSchG § 5 schreibt dies vor"}, {"text": "Ergonomische Arbeitsplätze bereitstellen", "correct": true, "because": "ArbSchG § 3 verlangt dies"}, {"text": "Keine Pausen gewähren", "correct": false, "because": "Widerspricht Pausenregelung"}, {"text": "Unterweisung über Gefahren bieten", "correct": true, "because": "ArbSchG § 12 fordert dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte des Arbeitsschutzes betreffen einen Fachinformatiker?', 3, '[{"text": "Ergonomische Bildschirmarbeitsplätze", "correct": true, "because": "ArbSchG § 3 schützt vor Gesundheitsrisiken"}, {"text": "Regelmäßige Pausen", "correct": true, "because": "ArbSchG § 3 regelt Pausen"}, {"text": "Arbeiten ohne Schutzausrüstung", "correct": false, "because": "Schutz ist vorgeschrieben"}, {"text": "Unterweisung über Gefahren", "correct": true, "because": "ArbSchG § 12 verlangt dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann ein Betrieb tun, um den Arbeitsschutz eines Fachinformatikers sicherzustellen?', 4, '[{"text": "Arbeitsplatz ergonomisch gestalten", "correct": true, "because": "ArbSchG § 3 fordert dies"}, {"text": "Gefährdungen beurteilen", "correct": true, "because": "ArbSchG § 5 ist Pflicht"}, {"text": "Nur lange Arbeitszeiten anordnen", "correct": false, "because": "Widerspricht Schutzvorschriften"}, {"text": "Unterweisung durchführen", "correct": true, "because": "ArbSchG § 12 schreibt dies vor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der Arbeitsschutzvorschriften für einen Fachinformatiker nicht einhält?', 3, '[{"text": "Bußgelder durch Behörden", "correct": true, "because": "ArbSchG Verstöße werden sanktioniert"}, {"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK kann einschreiten"}, {"text": "Keine Folgen", "correct": false, "because": "Verstoß hat Konsequenzen"}, {"text": "Schadensersatzforderungen", "correct": true, "because": "Bei Verletzung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat ein Betrieb nicht im Rahmen des Arbeitsschutzes für einen Fachinformatiker?', 3, '[{"text": "Gefährdungsbeurteilung durchführen", "correct": false, "because": "ArbSchG § 5 verlangt dies"}, {"text": "Ergonomische Arbeitsplätze bereitstellen", "correct": false, "because": "ArbSchG § 3 fordert dies"}, {"text": "Arbeiten ohne Pausen anordnen", "correct": true, "because": "Widerspricht ArbSchG § 3"}, {"text": "Unterweisung über Gefahren bieten", "correct": false, "because": "ArbSchG § 12 schreibt dies vor"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Betrieb muss Arbeitsschutzvorschriften für einen Fachinformatiker einhalten. b) Pausen sind nicht vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Arbeitsschutz Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betrieb muss einen Fachinformatiker über Gefahren unterweisen. b) Ergonomische Arbeitsplätze sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unterweisung Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Gefährdungsbeurteilungen sind für Fachinformatiker vorgeschrieben. b) Der Betrieb kann Arbeitsschutz ignorieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beurteilung Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Betrieb muss Pausen für einen Fachinformatiker gewähren. b) Arbeitsschutz gilt nur für gefährliche Berufe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pausen vorgeschrieben, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Betrieb muss ergonomische Bedingungen für einen Fachinformatiker sicherstellen. b) Verstöße gegen Arbeitsschutz haben keine Folgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergonomie Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

